<?php require_once __DIR__.'/../config/config.php';role_required(['editor','editor_in_chief']);$pageTitle='Reviewers';$rows=db()->query("SELECT full_name,email,affiliation,expertise FROM users WHERE role='reviewer' AND active=1 ORDER BY full_name")->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">Reviewer Directory</h1><div class="panel"><table><tr><th>Name</th><th>Email</th><th>Affiliation</th><th>Expertise</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['affiliation'])?></td><td><?=e($r['expertise'])?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>